  // ---------------- ACCESSORIES ----------------
  static void _acc(
    Canvas canvas,
    Rect r,
    List<List<_SpriteLayer>> table,
    int id,
    Color skin,
    Color hair,
  ) {
    if (id <= 0 || id >= table.length) return;
    _paintSprite(
      canvas,
      r,
      table[id],
      _palette(skin, hair, Colors.white, Colors.white),
    );
  }

  static void drawGlasses(
    Canvas canvas,
    Rect r,
    int style,
    Color skin,
    Color hair,
  ) => _acc(canvas, r, _glassesLayers, style, skin, hair);
  static void drawHat(
    Canvas canvas,
    Rect r,
    int style,
    Color skin,
    Color hair,
  ) => _acc(canvas, r, _hatLayers, style, skin, hair);
  static void drawHairClip(
    Canvas canvas,
    Rect r,
    int style,
    Color skin,
    Color hair,
  ) => _acc(canvas, r, _clipLayers, style, skin, hair);
  static void drawEarrings(
    Canvas canvas,
    Rect r,
    int style,
    Color skin,
    Color hair,
  ) => _acc(canvas, r, _earringLayers, style, skin, hair);
  static void drawNeckItem(
    Canvas canvas,
    Rect r,
    int style,
    Color skin,
    Color hair,
  ) => _acc(canvas, r, _neckLayers, style, skin, hair);
  static void drawFaceExtra(
    Canvas canvas,
    Rect r,
    int style,
    Color skin,
    Color hair,
  ) => _acc(canvas, r, _extraLayers, style, skin, hair);

  static double hatHairClip(int style) =>
      (style > 0 && style < _hatHairClipY.length) ? _hatHairClipY[style] : -1.0;

