  void _openAvatarCustomizer() {
    int category = 0;
    HapticFeedback.lightImpact();
    _loadRewards();

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        // Rebuild the sheet whenever this screen's state changes (e.g. the
        // coin balance finishes loading after the sheet is already open).
        return AnimatedBuilder(
          animation: _sheetRefresh,
          builder: (_, __) => StatefulBuilder(
          builder: (context, setModalState) {
            return ClipRRect(
              borderRadius: const BorderRadius.vertical(
                top: Radius.circular(34),
              ),
              child: Container(
                height: MediaQuery.of(context).size.height * 0.88,
                color: const Color(0xFFEEF3FB),
                child: Column(
                  children: [
                    // ---------- Sky header + live preview ----------
                    Container(
                      width: double.infinity,
                      clipBehavior: Clip.antiAlias,
                      decoration: const BoxDecoration(
                        gradient: _headerGradient,
                        borderRadius: BorderRadius.vertical(
                          bottom: Radius.circular(30),
                        ),
                      ),
                      child: SafeArea(
                        bottom: false,
                        child: Column(
                          children: [
                            const SizedBox(height: 10),
                            Container(
                              width: 44,
                              height: 5,
                              decoration: BoxDecoration(
                                color: Colors.white.withValues(alpha: 0.6),
                                borderRadius: BorderRadius.circular(10),
                              ),
                            ),
                            const SizedBox(height: 6),
                            SizedBox(
                              height: 52,
                              // Stack so the title is centred on the whole width,
                              // not just the space left between the two buttons.
                              child: Stack(
                                alignment: Alignment.center,
                                children: [
                                  const Text(
                                    'แต่งตัวอวตาร',
                                    style: TextStyle(
                                      fontSize: 19,
                                      fontWeight: FontWeight.w900,
                                      color: Colors.white,
                                    ),
                                  ),
                                  Row(
                                    children: [
                                      const SizedBox(width: 10),
                                      InkWell(
                                        onTap: () => Navigator.pop(sheetContext),
                                        borderRadius: BorderRadius.circular(20),
                                        child: Container(
                                          width: 36,
                                          height: 36,
                                          decoration: BoxDecoration(
                                            color: Colors.white.withValues(
                                              alpha: 0.26,
                                            ),
                                            shape: BoxShape.circle,
                                          ),
                                          child: const Icon(
                                            Icons.close_rounded,
                                            color: Colors.white,
                                            size: 22,
                                          ),
                                        ),
                                      ),
