  Widget _categoryButton({
    required IconData icon,
    required String label,
    required bool selected,
    required VoidCallback onTap,
  }) {
    return Expanded(
      child: InkWell(
        onTap: () {
          HapticFeedback.selectionClick();
          onTap();
        },
        borderRadius: BorderRadius.circular(20),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 220),
          // FIX: this used to be Curves.easeOutBack. That curve overshoots past 1.0,
          // so while the shadow faded out its blurRadius went NEGATIVE for a frame
          // and Flutter flashed an error every time you switched category tab.
          // easeOutCubic never overshoots.
          curve: Curves.easeOutCubic,
          margin: const EdgeInsets.symmetric(horizontal: 4),
          padding: const EdgeInsets.symmetric(vertical: 10),
          // Both states now have the SAME shape (one gradient + one shadow), so the
          // animation only blends colours instead of scaling a missing gradient /
          // shadow in and out.
          decoration: BoxDecoration(
            gradient:
                selected
                    ? _brandGradient
                    : const LinearGradient(
                      colors: [Color(0xFFF1F6FF), Color(0xFFF1F6FF)],
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                    ),
            borderRadius: BorderRadius.circular(20),
            boxShadow: [
              BoxShadow(
                color: const Color(
                  0xFF3B73F5,
                ).withValues(alpha: selected ? 0.35 : 0.0),
                blurRadius: 10,
                offset: const Offset(0, 5),
              ),
            ],
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                icon,
                color: selected ? Colors.white : const Color(0xFF8FA3C8),
                size: 24,
              ),
              const SizedBox(height: 4),
              Text(
                label,
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                  color: selected ? Colors.white : const Color(0xFF8FA3C8),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildGenderCategory(StateSetter setModalState) {
    Widget genderCard({
      required String gender,
      required IconData icon,
      required String label,
      required List<Color> gradientColors,
    }) {
      final bool isSelected = selectedGender == gender;
      return Expanded(
        child: GestureDetector(
          onTap: () {
            HapticFeedback.selectionClick();
            setState(() {
              selectedGender = gender;
              selectedHairStyle = 0;
              selectedOutfit = 0;
              selectedGlasses = 0;
              selectedHat = 0;
              selectedClip = 0;
              selectedEarring = 0;
              selectedNeck = 0;
              selectedExtra = 0;
            });
            _syncProfile();
            setModalState(() {});
          },
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 220),
            curve: Curves.easeOut,
            height: 148,
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(28),
              gradient:
                  isSelected
                      ? LinearGradient(
                        colors: gradientColors,
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                      )
                      : null,
              color: isSelected ? null : Colors.white,
              border: Border.all(
                color: isSelected ? Colors.white : const Color(0xFFDCE9FF),
                width: 2.5,
              ),
              boxShadow:
                  isSelected
                      ? [
                        BoxShadow(
                          color: gradientColors.first.withValues(alpha: 0.35),
                          blurRadius: 18,
                          offset: const Offset(0, 10),
                        ),
                      ]
                      : [
                        BoxShadow(
                          color: Colors.black.withValues(alpha: 0.03),
                          blurRadius: 8,
                          offset: const Offset(0, 3),
                        ),
                      ],
            ),
            child: Stack(
              children: [
                if (isSelected)
                  Positioned(top: 10, right: 10, child: _checkBadge()),
                Center(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Container(
                        width: 56,
                        height: 56,
                        decoration: BoxDecoration(
                          color:
                              isSelected
                                  ? Colors.white.withValues(alpha: 0.22)
                                  : gradientColors.first.withValues(alpha: 0.10),
                          shape: BoxShape.circle,
                        ),
                        child: Icon(
                          icon,
                          size: 30,
                          color:
                              isSelected ? Colors.white : gradientColors.first,
                        ),
                      ),
                      const SizedBox(height: 12),
                      Text(
                        label,
                        style: TextStyle(
                          fontSize: 15,
                          fontWeight: FontWeight.w800,
                          color:
                              isSelected
                                  ? Colors.white
                                  : const Color(0xFF1E1B2E),
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    }

    return _sheetCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _sectionTitle('เลือกเพศอวตาร'),
          Row(
            children: [
              genderCard(
                gender: 'female',
                icon: Icons.female_rounded,
                label: 'หญิง',
                gradientColors: const [Color(0xFFFF5FA2), Color(0xFFFF9CC8)],
              ),
              const SizedBox(width: 14),
              genderCard(
                gender: 'male',
                icon: Icons.male_rounded,
                label: 'ชาย',
                gradientColors: const [Color(0xFF3B73F5), Color(0xFF6C9BFF)],
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _swatchCircle({
    required Color color,
    required bool selected,
    required VoidCallback onTap,
    double size = 46,
  }) {
    final bool isLight =
        ThemeData.estimateBrightnessForColor(color) == Brightness.light;
    return GestureDetector(
      onTap: () {
        HapticFeedback.selectionClick();
        onTap();
      },
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 180),
        width: size,
        height: size,
        decoration: BoxDecoration(
          color: color,
          shape: BoxShape.circle,
          border: Border.all(
            color: selected ? const Color(0xFFFFB627) : Colors.white,
            width: selected ? 3.5 : 2.5,
          ),
          boxShadow:
              selected
                  ? [
                    BoxShadow(
                      color: const Color(0xFFFFB627).withValues(alpha: 0.45),
                      blurRadius: 10,
                      offset: const Offset(0, 4),
                    ),
                  ]
                  : [
                    BoxShadow(
                      color: Colors.black.withValues(alpha: 0.10),
                      blurRadius: 5,
                      offset: const Offset(0, 2),
                    ),
                  ],
        ),
        child:
            selected
                ? Icon(
                  Icons.check_rounded,
                  size: size * 0.46,
                  color: isLight ? Colors.black87 : Colors.white,
                )
                : null,
      ),
    );
  }

